head.script:
// 테스트 설명, 유효성 값 설정
//  - 처리 순서 축("다음과 같은 처리가 완료된 후 onblur 이벤트가 발생합니다." 의 하위절 3건)을 담당한다.
//  - 발생 조건(포커스 해제 / e 전달 / disabled, readOnly 미발생)은 secret_E_onblur_1.xml 에서 검증한다.
//  - validator / ref / onFocusClass 는 하위절의 전제 조건으로만 고정 설정하며 각 속성 자체의 기능은 검증하지 않는다.
scwin.tData = {
    "description" : "[secret > E > onblur]<br/>Secret 컴포넌트가 포커스를 잃을 때 발생합니다.",
    "validation" : [
        "validator 속성의 사용자 정의 함수 반환값이 적용된 후 onblur 이벤트가 발생합니다.",
        "ref 속성으로 바인딩한 DataCollection 에 입력값이 적용된 후 onblur 이벤트가 발생합니다.",
        "onFocusClass 속성에 의해 추가된 클래스가 제거된 후 onblur 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdm_ref)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트(초기값 secret)이며 validator=scwin.fn_validator (입력값 뒤에 _v 를 붙여 반환), ref=data:gdm_ref.key1, onFocusClass=onFocusClass (배경 노랑) 로 고정 설정\n[절차] target1 클릭 -> 값 입력(예: abc) -> 바깥 영역 클릭하여 포커스 해제\n[확인] 사용자 정의 함수 실행 시점 줄과 onblur 핸들러 시점 줄의 입력값, 바인딩 데이터 값, class 비교"', '', 'label1');

    let properties = {
        validator : "scwin.fn_validator",
        ref : "data:gdm_ref.key1",
        onFocusClass : "onFocusClass",
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onblur"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정 -> gdm_ref.key1 도 secret)
    await $c.gcm.createBasicSecret(cList, eList);
}



// 입력값 (password 라 화면으로 읽을 수 없으므로 글자 수 병기)
scwin.fn_len = function (strValue) {
    if (strValue === undefined || strValue === null)
        return String(strValue);

    return strValue + " (" + strValue.length + "자)";
}



// validator 로 설정되는 사용자 정의 함수 - onblur 이전 시점의 바인딩 데이터 값과 class 를 출력 (validation 1, 2, 3 판정 출력)
scwin.fn_validator = function (val, id) {
    let rtn = val + "_v";

    wf_body_bottom.getObj("scwin").setReturnValue("사용자 정의 함수 실행 시점 -> 파라미터 val : " + scwin.fn_len(val) + " / 반환값 : " + scwin.fn_len(rtn) + " / 바인딩 데이터 값 : " + scwin.fn_len(gdm_ref.get("key1")) + " / class : " + target1.render.className + " / bg : " + target1.getStyle("background-color"));

    return rtn;
}



// 테스트 샘플의 이벤트 처리 (포커스 해제) - validation 1, 2, 3 판정 출력
scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("onblur 핸들러 시점 -> 입력값 : " + scwin.fn_len(target1.getValue()) + " / 바인딩 데이터 값 : " + scwin.fn_len(gdm_ref.get("key1")) + " / class : " + target1.render.className + " / bg : " + target1.getStyle("background-color"));
}
